<!-- ============================================
     COLOR EXTRACTION
     Extracts dominant color from product image,
     darkens + saturates it, sets as bottom-half bg.
     Ensures WCAG 4.5:1 contrast with white text.
     ============================================ -->
<script>
function extractSplitColor(img) {
  try {
    var c = document.createElement('canvas'),
        x = c.getContext('2d'),
        s = 64;
    c.width = s; c.height = s;
    x.drawImage(img, 0, 0, s, s);
    var d = x.getImageData(0, 0, s, s).data,
        rS = 0, gS = 0, bS = 0, n = 0;

    /* Sample every 4th pixel, prefer saturated mid-tones */
    for (var i = 0; i < d.length; i += 16) {
      var r = d[i], g = d[i+1], b = d[i+2],
          br = (r + g + b) / 3;
      if (br > 25 && br < 230) {
        var mx = Math.max(r, g, b), mn = Math.min(r, g, b),
            sa = mx === 0 ? 0 : (mx - mn) / mx;
        if (sa > 0.08) { rS += r; gS += g; bS += b; n++; }
      }
    }

    /* Fallback: include all mid-tone pixels if too few saturated */
    if (n < 10) {
      for (var i = 0; i < d.length; i += 16) {
        var r = d[i], g = d[i+1], b = d[i+2],
            br = (r + g + b) / 3;
        if (br > 30 && br < 225) { rS += r; gS += g; bS += b; n++; }
      }
    }

    if (n > 0) {
      var rA = Math.round(rS / n),
          gA = Math.round(gS / n),
          bA = Math.round(bS / n);

      /* Boost saturation 30% */
      var mx = Math.max(rA, gA, bA),
          mn = Math.min(rA, gA, bA),
          md = (mx + mn) / 2;
      if (mx !== mn) {
        rA = Math.min(255, Math.round((rA - md) * 1.3 + md));
        gA = Math.min(255, Math.round((gA - md) * 1.3 + md));
        bA = Math.min(255, Math.round((bA - md) * 1.3 + md));
      }

      /* Darken to ~35% for rich deep background */
      var dk = 0.35,
          rD = Math.round(rA * dk),
          gD = Math.round(gA * dk),
          bD = Math.round(bA * dk);

      /* Ensure WCAG 4.5:1 with white text
         (max channel ≤ 55 ensures relative luminance ≤ 0.053) */
      var maxCh = Math.max(rD, gD, bD);
      if (maxCh > 55) {
        var sc = 55 / maxCh;
        rD = Math.round(rD * sc);
        gD = Math.round(gD * sc);
        bD = Math.round(bD * sc);
      }

      var color = 'rgb(' + rD + ',' + gD + ',' + bD + ')';
      var root = document.documentElement.style;
      root.setProperty('--split-bg', color);
      root.setProperty('--split-r', rD);
      root.setProperty('--split-g', gD);
      root.setProperty('--split-b', bD);
    }
  } catch(e) { /* Silently fail — default color remains */ }
}

