  var img = document.querySelector('.top-half .product-image');
  if (img && img.complete && img.naturalWidth > 0) {
    extractSplitColor(img);
  } else if (img) {
    img.addEventListener('load', function() { extractSplitColor(this); });
  }
});
</script>
