<script>
function extractAccentColor(img) {
  try {
    var c = document.createElement('canvas'),
        x = c.getContext('2d'),
        s = 64;
    c.width = s; c.height = s;
    x.drawImage(img, 0, 0, s, s);
    var d = x.getImageData(0, 0, s, s).data,
        rS = 0, gS = 0, bS = 0, n = 0;

    for (var i = 0; i < d.length; i += 16) {
      var r = d[i], g = d[i+1], b = d[i+2],
          br = (r + g + b) / 3;
      if (br > 25 && br < 230) {
        var mx = Math.max(r, g, b), mn = Math.min(r, g, b),
            sa = mx === 0 ? 0 : (mx - mn) / mx;
        if (sa > 0.08) { rS += r; gS += g; bS += b; n++; }
      }
    }

    if (n < 10) {
      for (var i = 0; i < d.length; i += 16) {
        var r = d[i], g = d[i+1], b = d[i+2],
            br = (r + g + b) / 3;
        if (br > 30 && br < 225) { rS += r; gS += g; bS += b; n++; }
      }
    }

    if (n > 0) {
      var rA = Math.round(rS / n),
          gA = Math.round(gS / n),
          bA = Math.round(bS / n);

      var mx = Math.max(rA, gA, bA),
          mn = Math.min(rA, gA, bA),
          md = (mx + mn) / 2;
      if (mx !== mn) {
        rA = Math.min(255, Math.round((rA - md) * 1.3 + md));
        gA = Math.min(255, Math.round((gA - md) * 1.3 + md));
        bA = Math.min(255, Math.round((bA - md) * 1.3 + md));
      }

      var dk = 0.85,
          rD = Math.round(rA * dk),
          gD = Math.round(gA * dk),
          bD = Math.round(bA * dk);

      function relLuminance(r, g, b) {
        var rs = r / 255, gs = g / 255, bs = b / 255;
        rs = rs <= 0.03928 ? rs / 12.92 : Math.pow((rs + 0.055) / 1.055, 2.4);
        gs = gs <= 0.03928 ? gs / 12.92 : Math.pow((gs + 0.055) / 1.055, 2.4);
        bs = bs <= 0.03928 ? bs / 12.92 : Math.pow((bs + 0.055) / 1.055, 2.4);
        return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
      }

      var lum = relLuminance(rD, gD, bD);
      if (lum > 0.18) {
        var sc = 0.18 / lum;
        rD = Math.round(Math.min(255, rD * sc));
        gD = Math.round(Math.min(255, gD * sc));
        bD = Math.round(Math.min(255, bD * sc));
      }

      var color = 'rgb(' + rD + ',' + gD + ',' + bD + ')';
      document.documentElement.style.setProperty('--accent', color);
      document.documentElement.style.setProperty('--accent-r', rD);
      document.documentElement.style.setProperty('--accent-g', gD);
      document.documentElement.style.setProperty('--accent-b', bD);
      document.documentElement.style.setProperty('--accent-light', 'rgba(' + rD + ',' + gD + ',' + bD + ',0.08)');
      document.documentElement.style.setProperty('--accent-soft', 'rgba(' + rD + ',' + gD + ',' + bD + ',0.15)');
    }
  } catch(e) {}
}

