     COLOR EXTRACTION
     Extracts dominant color, boosts brightness,
     applies to accent sticker/tape elements.
     Kept playful — doesn't dominate the design.
     ============================================ -->
<script>
function extractStoryColor(img) {
  try {
    var c = document.createElement('canvas'),
        x = c.getContext('2d'),
        s = 64;
    c.width = s; c.height = s;
    x.drawImage(img, 0, 0, s, s);
    var d = x.getImageData(0, 0, s, s).data,
        rS = 0, gS = 0, bS = 0, n = 0;

    for (var i = 0; i < d.length; i += 16) {
      var r = d[i], g = d[i+1], b = d[i+2],
          br = (r + g + b) / 3;
      if (br > 25 && br < 230) {
        var mx = Math.max(r, g, b), mn = Math.min(r, g, b),
            sa = mx === 0 ? 0 : (mx - mn) / mx;
        if (sa > 0.08) { rS += r; gS += g; bS += b; n++; }
      }
    }
    if (n < 10) {
      for (var i = 0; i < d.length; i += 16) {
        var r = d[i], g = d[i+1], b = d[i+2],
            br = (r + g + b) / 3;
        if (br > 30 && br < 225) { rS += r; gS += g; bS += b; n++; }
      }
    }

    if (n > 0) {
      var rA = Math.round(rS / n),
          gA = Math.round(gS / n),
          bA = Math.round(bS / n);

      /* Boost saturation 30% */
      var mx = Math.max(rA, gA, bA),
          mn = Math.min(rA, gA, bA),
          md = (mx + mn) / 2;
      if (mx !== mn) {
        rA = Math.min(255, Math.round((rA - md) * 1.3 + md));
        gA = Math.min(255, Math.round((gA - md) * 1.3 + md));
        bA = Math.min(255, Math.round((bA - md) * 1.3 + md));
      }

      /* Brighten for playful sticker accent */
      rA = Math.min(255, Math.round(rA * 0.75 + 64));
      gA = Math.min(255, Math.round(gA * 0.75 + 64));
      bA = Math.min(255, Math.round(bA * 0.75 + 64));

      var root = document.documentElement.style;
      root.setProperty('--accent', 'rgb(' + rA + ',' + gA + ',' + bA + ')');
    }
  } catch(e) { /* Default orange accent remains */ }
}

document.addEventListener('DOMContentLoaded', function() {
  var img = document.querySelector('.product-image-area .product-image');
  if (img && img.complete && img.naturalWidth > 0) {
    extractStoryColor(img);
  } else if (img) {
    img.addEventListener('load', function() { extractStoryColor(this); });
  }
});
</script>
